        HCCL_DATA_TYPE_HIF8 = 14,    /* hif8 */
        HCCL_DATA_TYPE_FP8E4M3 = 15, /* fp8e4m3 */
        HCCL_DATA_TYPE_FP8E5M2 = 16, /* fp8e5m2 */
