                                          vector_<dtype> src1,
                                          vector_bool mask)

// 通过引用参数输出结果（占位符形式）
__simd_callee__ inline void asc_lt(vector_bool& dst,
                                   vector_<dtype> src0,
                                   vector_<dtype> src1,
                                   vector_bool mask)
```

