    asc_half2float(dst, src, mask, ASC_POSITION_EVEN);
    asc_storealign(reinterpret_cast<__ubuf__ float*>(output), dst, mask);
}

__global__ __vector__ void asc_half2float_kernel(__gm__ uint8_t* output, __gm__ uint8_t* input)
{
    asc_init();
