# VL表示矢量数据寄存器位宽，取值256字节。
def asc_int642int32(dst, src, mask, dst_pos):
    offset = 0 if dst_pos == ASC_POSITION_EVEN else 1
    for i in range(VL // 8):
        dst[2 * i] = 0
        dst[2 * i + 1] = 0
        if mask[i]:
            dst[2 * i + offset] = int32_t(src[i])  # int64_t -> int32_t
