                                                      vector_<dtype1> shift,
                                                      vector_bool mask)

// 通过引用参数输出结果（占位符形式）
__simd_callee__ inline void asc_shiftright(vector_<dtype0>& dst,
                                           vector_<dtype0> src,
                                           vector_<dtype1> shift,
                                           vector_bool mask)
```

