__global__ __vector__ void asc_clear_nthbit_kernel(__gm__ uint64_t* output)
{
    asc_init();
    // 确保普通Scalar读取到GM中的最新输入。
    asc_dcci_single(output);
    asc_sync_data_barrier(mem_dsb_t::DSB_ALL);
