        value += asc_shfl_xor(value, 2, 32);
        value += asc_shfl_xor(value, 4, 32);
        value += asc_shfl_xor(value, 8, 32);
        value += asc_shfl_xor(value, 16, 32);

        dst[idx] = value; // 归约求和结果位于每个Warp内所有线程
    }
    ```

